-- CreateEnum
CREATE TYPE "ScheduleStatus" AS ENUM ('DRAFT', 'REVIEW', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "AssignmentStatus" AS ENUM ('PENDING', 'CONFIRMED', 'DECLINED', 'REPLACED', 'PRESENT', 'ABSENT');
CREATE TYPE "RuleSeverity" AS ENUM ('REQUIRED', 'PREFERRED', 'INFO');
CREATE TYPE "RuleType" AS ENUM ('ALLOWED_ROLE', 'REQUIRED_ROLE', 'MAX_ASSIGNMENTS', 'MIN_DAYS_OFF', 'MIN_INTERVAL', 'ALLOWED_DAYS', 'ROTATE_STATIONS', 'BALANCE_LOAD', 'AVOID_CONSECUTIVE', 'REQUIRED_PAIR', 'FORBIDDEN_PAIR');
CREATE TABLE "Church" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "timezone" TEXT NOT NULL DEFAULT 'America/Sao_Paulo', "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MinistryRole" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "abbreviation" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, UNIQUE("churchId", "name"));
CREATE TABLE "Worker" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "roleId" TEXT NOT NULL REFERENCES "MinistryRole"("id"), "fullName" TEXT NOT NULL, "displayName" TEXT NOT NULL, "phone" TEXT, "email" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "monthlyMaximum" INTEGER, "minimumGapDays" INTEGER DEFAULT 2, "notes" TEXT);
CREATE INDEX "Worker_churchId_active_idx" ON "Worker"("churchId", "active");
CREATE TABLE "Station" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "defaultQuantity" INTEGER NOT NULL DEFAULT 1, "active" BOOLEAN NOT NULL DEFAULT true, UNIQUE("churchId", "name"));
CREATE TABLE "WorkerStation" ("workerId" TEXT NOT NULL REFERENCES "Worker"("id") ON DELETE CASCADE, "stationId" TEXT NOT NULL REFERENCES "Station"("id") ON DELETE CASCADE, "enabled" BOOLEAN NOT NULL DEFAULT true, "preference" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY("workerId", "stationId"));
CREATE TABLE "EventType" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "weekday" INTEGER, "defaultTime" TEXT, "color" TEXT NOT NULL DEFAULT '#1E3A5F', "active" BOOLEAN NOT NULL DEFAULT true, UNIQUE("churchId", "code"));
CREATE TABLE "Event" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "eventTypeId" TEXT NOT NULL REFERENCES "EventType"("id"), "title" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), "canceled" BOOLEAN NOT NULL DEFAULT false, "notes" TEXT);
CREATE INDEX "Event_churchId_startsAt_idx" ON "Event"("churchId", "startsAt");
CREATE TABLE "EventRequirement" ("id" TEXT PRIMARY KEY, "eventId" TEXT NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "stationId" TEXT NOT NULL REFERENCES "Station"("id"), "quantity" INTEGER NOT NULL DEFAULT 1, "required" BOOLEAN NOT NULL DEFAULT true, UNIQUE("eventId", "stationId"));
CREATE TABLE "Availability" ("id" TEXT PRIMARY KEY, "workerId" TEXT NOT NULL REFERENCES "Worker"("id") ON DELETE CASCADE, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "kind" TEXT NOT NULL, "reason" TEXT);
CREATE INDEX "Availability_workerId_startsAt_endsAt_idx" ON "Availability"("workerId", "startsAt", "endsAt");
CREATE TABLE "Schedule" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "periodStart" TIMESTAMP(3) NOT NULL, "periodEnd" TIMESTAMP(3) NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "status" "ScheduleStatus" NOT NULL DEFAULT 'DRAFT', "publicToken" TEXT NOT NULL UNIQUE, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Assignment" ("id" TEXT PRIMARY KEY, "scheduleId" TEXT NOT NULL REFERENCES "Schedule"("id") ON DELETE CASCADE, "eventId" TEXT NOT NULL REFERENCES "Event"("id") ON DELETE CASCADE, "stationId" TEXT NOT NULL REFERENCES "Station"("id"), "workerId" TEXT NOT NULL REFERENCES "Worker"("id"), "origin" TEXT NOT NULL DEFAULT 'AUTOMATIC', "status" "AssignmentStatus" NOT NULL DEFAULT 'PENDING', "notes" TEXT, UNIQUE("scheduleId", "eventId", "stationId", "workerId"));
CREATE TABLE "DistributionRule" ("id" TEXT PRIMARY KEY, "churchId" TEXT NOT NULL REFERENCES "Church"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "description" TEXT, "type" "RuleType" NOT NULL, "severity" "RuleSeverity" NOT NULL, "priority" INTEGER NOT NULL DEFAULT 50, "active" BOOLEAN NOT NULL DEFAULT true, "scope" JSONB NOT NULL, "parameters" JSONB NOT NULL, "violationMessage" TEXT NOT NULL, "validFrom" TIMESTAMP(3), "validUntil" TIMESTAMP(3));
CREATE INDEX "DistributionRule_churchId_active_idx" ON "DistributionRule"("churchId", "active");
